319: function applyMove(attacker, defender, move, done) {
320:   if(!battle||battle.finished)return
321:   if(move.type==='defend') {
322:     battle.guard[attacker]=true; battle.sta[attacker]=Math.min(battle.maxSta[attacker],battle.sta[attacker]+Math.abs(move.cost));
