324:   }
325:   const cost=Math.max(0,move.cost)
326:   if(battle.sta[attacker]<cost) { battle.sta[attacker]=Math.min(battle.maxSta[attacker],battle.sta[attacker]+12); toast(`${battle[attacker].name} is winded and recovers 12 stamina.`); done(); return }
327:   battle.sta[attacker]-=cost
328:   if(Math.random()>move.acc) { toast(`${move.name} missed!`); done(); return }
329:   let damage=Math.round((10+move.power*16)*(0.78+statsOf(battle[attacker]).power/180)*(0.82+Math.random()*.36))
330:   if(move.crit&&Math.random()<move.crit)damage=Math.round(damage*1.5)
331:   if(battle.guard[defender]&&!move.pierce){damage=Math.ceil(damage*.48);battle.guard[defender]=false;toast(`${battle[defender].name} guarded the hit!`)}
332:   battle.hp[defender]=Math.max(0,battle.hp[defender]-damage)
333:   const defenderSide=attacker==='player'?'foe':'player'
334:   world.battleLunge(attacker,()=>world.hitReact(defenderSide,done))
335:   world.burst?.({x:attacker==='player'?2: -2,y:1.5,z:.3},phenotype(battle[attacker].genome).accentColor,15)
336:   toast(`${move.name} dealt ${damage} damage.`)
337:   if(move.buff==='evade')battle.guard[attacker]=true
338: }
