@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;600;700&display=swap');

:root{font-family:'Space Grotesk',sans-serif;color:#e9eee5;background:#0d1411;font-synthesis:none;text-rendering:optimizeLegibility;--bg:#0d1411;--panel:#131c17;--panel2:#18231c;--line:#29362e;--muted:#91a096;--lime:#d7fa77;--mint:#77e6bf;--mono:'DM Mono',monospace}
*{box-sizing:border-box}
body{margin:0;min-width:320px;min-height:100vh;background:radial-gradient(ellipse at 58% -20%,#26372b 0,transparent 43%),var(--bg)}
button,input,select{font:inherit}
button{color:inherit;cursor:pointer}
button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--lime);outline-offset:3px}
button:disabled{opacity:.45;cursor:not-allowed}
.shell{min-height:100vh}
.topbar{height:74px;padding:0 32px;border-bottom:1px solid #26332a;display:flex;align-items:center;justify-content:space-between;background:#0e1612;position:relative;z-index:3}
.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:#eef3e9}
.brand-mark{width:34px;height:34px;border:1px solid #658044;color:var(--lime);border-radius:11px;display:grid;place-content:center;font-size:19px;font-weight:700;position:relative}
.brand-mark span{position:absolute;font-size:10px;right:4px;top:2px}
.brand-copy{font-size:13px;font-weight:700;letter-spacing:2px;line-height:1.15}
.brand-copy span{display:block;color:#a8b6a8;font-size:9px;letter-spacing:3.3px}
.top-status{font:10px var(--mono);letter-spacing:1.2px;color:#b9c5b9;display:flex;align-items:center;gap:9px}
.live-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#79e6a8;box-shadow:0 0 11px #79e6a877}
.season{border-left:1px solid #354239;margin-left:10px;padding-left:17px;color:#859388}
.resources{display:flex;gap:23px}
.resource{display:grid;grid-template-columns:18px auto;grid-template-rows:17px 11px;align-items:center;column-gap:5px}
.resource>span{grid-row:1/3;color:var(--lime);font-size:17px}
.resource b{font:14px var(--mono);color:#eaf1dd}
.resource small{font:8px var(--mono);letter-spacing:1.2px;color:#829086}
.workspace{display:grid;grid-template-columns:236px minmax(420px,1fr) 354px;min-height:calc(100vh - 74px);max-width:1800px;margin:auto}
.left-rail{border-right:1px solid #27342b;padding:25px 16px 16px;display:flex;flex-direction:column;min-height:calc(100vh - 74px);background:#101813}
.section-label,.eyebrow{font:9px var(--mono);letter-spacing:1.6px;color:#90a092}
.section-label{padding:0 7px 15px;display:flex;justify-content:space-between}
.section-label span{color:var(--lime)}
.roster{display:flex;flex-direction:column;gap:7px}
.roster-card{width:100%;border:1px solid transparent;background:transparent;display:flex;align-items:center;text-align:left;padding:9px 7px;gap:9px;border-radius:7px;transition:.18s}
.roster-card:hover{background:#19251c;border-color:#2b3b2e}
.roster-card.selected{background:#1b281d;border-color:#53643c}
.roster-num{font:9px var(--mono);color:#68786c}
.roster-avatar{width:36px;height:36px;flex:none;border-radius:50%;background:radial-gradient(circle at 38% 30%,var(--creature-accent),var(--creature-color) 66%,#24352a);border:1px solid #81926955;position:relative;overflow:hidden}
.roster-avatar:before{content:'';position:absolute;width:18px;height:13px;left:8px;top:12px;border-radius:60% 48% 42% 52%;background:var(--creature-color);filter:brightness(1.35);box-shadow:8px 4px 0 -3px #162018}
.roster-avatar i{position:absolute;left:24px;top:16px;width:3px;height:3px;border-radius:50%;background:#152019}
.roster-info{min-width:0;flex:1;display:flex;flex-direction:column;gap:3px}
.roster-info>b{font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.roster-info>small{font:8px var(--mono);color:#87978a}
.roster-info>small i{font-style:normal;color:#59695b;margin:0 3px}
.roster-mini{height:2px;background:#334138;border-radius:4px;margin-top:3px}
.roster-mini i{height:100%;display:block;background:var(--mint);border-radius:4px}
.roster-rating{font:10px var(--mono);color:#d4e4b7}
.discover{margin-top:12px;padding:12px 9px;border:1px dashed #465a42;background:#18231a;color:#d9ebbd;border-radius:6px;font-size:10px;letter-spacing:.5px;text-align:left}
.discover small{float:right;color:var(--lime);font:9px var(--mono)}
.discover:hover{background:#243224;border-color:#94b76b}
.rail-spacer{flex:1;min-height:24px}
.sanctuary-card{border:1px solid #2a392f;background:linear-gradient(145deg,#19251d,#121a15);padding:13px;border-radius:8px;position:relative}
.sanctuary-orb{float:left;width:32px;height:32px;background:#283922;color:var(--lime);display:grid;place-content:center;border-radius:50%;margin-right:9px;font-size:18px}
.sanctuary-card>div:nth-child(2){display:flex;flex-direction:column;gap:3px;padding-top:2px}
.sanctuary-card>div:nth-child(2) b{font-size:10px;letter-spacing:1px}
.sanctuary-card>div:nth-child(2) span,.sanctuary-card p{font-size:9px;color:#91a094}
.live-tag{position:absolute;right:12px;top:17px;color:#8ce8af;font:8px var(--mono);font-style:normal}
.sanctuary-card p{clear:both;margin:15px 0 10px;line-height:1.5}
.harmony{height:3px;background:#344236;border-radius:5px;margin-bottom:7px}
.harmony i{display:block;width:78%;height:100%;background:var(--lime);border-radius:5px}
.sanctuary-card>small{font:8px var(--mono);letter-spacing:.65px;color:#829085}
.sanctuary-card>small b{float:right;color:#c7e88b}
.rail-footer{padding:14px 4px 0;color:#58665c;font:8px var(--mono);letter-spacing:.7px}
.stage-column{padding:24px 24px 21px;min-width:0}
.stage-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:17px}
.stage-head h1{font-size:23px;letter-spacing:-.7px;margin:6px 0 0;font-weight:600}
.stage-controls{display:flex;align-items:center;gap:7px}
.creature-count{font:9px var(--mono);color:#9ba99c;margin-right:8px}
.creature-count i{display:inline-block;width:6px;height:6px;background:#a5d86a;border-radius:50%;margin-right:6px}
.view-btn{border:1px solid #314037;background:#141e18;color:#97a69a;padding:8px 10px;border-radius:5px;font:9px var(--mono);letter-spacing:.4px}
.view-btn.active,.view-btn:hover{color:#e9f1dc;border-color:#66774d;background:#263321}
.viewport-wrap{height:clamp(370px,54vh,620px);min-height:340px;position:relative;border:1px solid #2b3a2f;border-radius:9px;overflow:hidden;background:#152019;box-shadow:0 14px 50px #0005}
.viewport{position:absolute;inset:0}
.viewport canvas{display:block;width:100%;height:100%;outline:none}
.viewport-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(0deg,#10181355,transparent 35%,#0b120e22),radial-gradient(ellipse,transparent 45%,#09100b55)}
.scene-tag,.camera-hint{position:absolute;z-index:1;bottom:15px;font:8px var(--mono);letter-spacing:1px;color:#d6e0d1;background:#101813b8;border:1px solid #63736345;border-radius:4px;padding:8px 10px;pointer-events:none}
.scene-tag{left:15px}
.scene-tag .live-dot{margin-right:7px;width:6px;height:6px}
.camera-hint{right:15px;color:#9eac9f}
.camera-hint b{color:var(--lime);margin:0 4px}
.stage-bottom{display:flex;align-items:center;justify-content:space-between;padding-top:16px;gap:12px}
.world-note{display:flex;align-items:center;gap:10px}
.world-note>span{color:var(--lime);font-size:18px}
.world-note div{display:flex;flex-direction:column;gap:4px}
.world-note b{font:9px var(--mono);letter-spacing:1px}
.world-note small{font-size:10px;color:#8b9b8e}
.stage-actions{display:flex;gap:8px}
.secondary-btn,.primary-btn{border-radius:5px;padding:10px 12px;font:9px var(--mono);letter-spacing:.6px;white-space:nowrap}
.secondary-btn{border:1px solid #3c4b3e;background:#18221b;color:#c5d0c3}
.secondary-btn:hover{border-color:#829468;background:#202d22}
.primary-btn{border:1px solid #d5ef8c;background:var(--lime);color:#1b2415;font-weight:500}
.primary-btn:hover{background:#e5ff9c}
.primary-btn b{margin-left:7px}
.right-panel{border-left:1px solid #27342b;padding:23px 20px 20px;background:#111a15;min-width:0}
.profile-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}
.profile-heading h2{margin:4px 0 0;font-size:16px;letter-spacing:.3px}
.icon-btn{width:30px;height:30px;border:1px solid #344237;border-radius:5px;background:#17221a;color:#aebbaf;font-size:17px;line-height:12px}
.identity{display:flex;gap:13px;align-items:center;padding-bottom:15px;border-bottom:1px solid #29362d}
.identity-art{position:relative;overflow:hidden;flex:none;width:91px;height:93px;border:1px solid #73875b55;border-radius:7px;background:radial-gradient(ellipse at 55% 40%,color-mix(in srgb,var(--creature-accent),transparent 30%),transparent 56%),linear-gradient(140deg,#293725,#19231b 68%);display:flex;align-items:center;justify-content:center}
.identity-art:after{content:'';position:absolute;inset:0;background:linear-gradient(130deg,#ffffff10,transparent 40%);pointer-events:none}
